INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (95, 172, 'BOPP/BOPET/BOPA Thermal Lamination Film (glossy and matte lamination)', '../upload/image/20180928/20180928231652_54813.jpg', '<p></p><p>BOPP/BOPET/BOPA Thermal Lamination Film (glossy and matte lamination)</p> <p>BOPP/BOPET/BOPA Thermal Lamination Film (glossy/matte) which were BOPP clear film coated with EVA.<br/> Spec.: 1.) Jumbo roll sizes: <br/> Total Thickness: 22-33UM (Mic.)<br/> Basic film thickness: 10,12,15,18,20 UM (Mic.) Width :325-1200MM<br/> Length:3000M (2000M,4000M,6000M,9000M).Inner core:76MM ,152MM 2.) Mini-roll sizes:Total Thickness :22-33UM (Mic.) Film thickness: 10,12,15,18,20 UM (Mic.) Width :325-1200MM<br/> Type:included BOPET thermal film (Polyester thermal lamination film with EVA),BOPA thermal film (nylon<br/> thermal lamination film with EVA), bopp thermal film (Polypropylene thermal lamination film with EVA)<br/> Length :100M,120M,150M,200M Inner core :1.5",1.8", 2.0",3" (Inches)<br/> Applications:Laminate the surface of Books, catalogs, samples, posters, printed paper, Food, medicines, cosmetics, gifts, wine boxes and other packaging film ,Drawings, documents, ads, pictures, display boards, etc.</p>', '2026-09-06 20:58:45');
