INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (95, 239, 'PET thermal lamination film', '../upload/image/20180928/20180928232519_88401.jpg', '<p></p><p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p><h2> <b><span style="font-family:Verdana;font-size:14pt;font-weight:bold;">Polyester based Thermal Lamination Film</span></b> </h2> <p><b></b><b></b><b></b><b></b><b></b></p> <p align="justify" style="text-align:justify;"> <b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">PROFILE </span></b><span style="font-family:Verdana;font-size:12pt;">: It is polyester based, both sides corona treated, uniformly extrusion coated with adhesive which enables lamination by heat and pressure with paper products. </span></p> <p align="justify" style="text-align:justify;"></p> <p><b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">FEATURES :</span></b></p> <p><span style="font-family:Verdana;font-size:12pt;">Fibre-tear bond strength with paper </span></p> <p><span style="font-family:Verdana;font-size:12pt;"> 2) Excellent optical properties. </span></p> <p><span style="font-family:Verdana;font-size:12pt;"> 3) Excellent resistance to elongation &amp; tear. </span></p> <p><span style="font-family:Verdana;font-size:12pt;"> 4) Offer increased productivity with simple operation.</span></p> <p></p> <p><b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">APPLICATIONS : </span></b><span style="font-family:Verdana;font-size:11pt;">Thermal lamination with all kinds of printed &amp; unprinted paper and paper boards like maps, book covers, posters, magazines, boxes, brochures etc.</span></p> <p><br/></p><p><b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">TYPICAL PROPERTIES:</span></b></p> <table border="1" cellspacing="0" style="margin:auto auto auto 9.9pt;border:currentColor;width:450pt;border-collapse:collapse;"> <tbody> <tr> <td style="border:1pt solid windowtext;background-color:transparent;" valign="top" width="216"> <p><b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">PROPERTY</span></b></p> </td> <td style="background-color:transparent;" valign="top" width="150"> <p align="center" style="text-align:center;"> <b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">UNIT</span></b></p> </td> <td style="background-color:transparent;" valign="top" width="126"> <p align="center" style="text-align:center;"> <b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">ASTM/ TEST #</span></b></p> </td> <td style="background-color:transparent;" valign="top" width="108"> <p align="center" style="text-align:center;"> <b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">30 PCT-2</span></b></p> <p align="center" style="text-align:center;"> <b><span style="font-family:Verdana;font-size:12pt;font-weight:bold;">(PDL)</span></b></p> </td> </tr> <tr> <td style="background-color:transparent;" valign="top" width="216"> <p><br/></p><p><b><span style="font-family:Verdana;font-size:11pt;font-weight:bold;">PHYSICAL DATA</span></b></p> <p><span style="font-family:Verdana;font-size:11pt;">Average Thickness</span></p> <p><span style="font-family:Verdana;font-size:11pt;">Average GSM</span></p> <p><span style="font-family:Verdana;font-size:11pt;">Yield</span></p> <p><span style="font-family:Verdana;font-size:11pt;">Wettability (min)</span></p> <p><span style="font-family:Verdana;font-size:11pt;">Coefficient of friction (F-F)</span></p> <p><b><span style="font-family:Verdana;font-size:11pt;font-weight:bold;">OPTICAL DATA</span></b></p> <p><span style="font-family:Verdana;font-size:11pt;">Gloss at 45 </span><sup><span style="font-family:Verdana;font-size:11pt;vertical-align:super;">0 </span></sup><span style="font-family:Verdana;font-size:11pt;">(min)</span></p> <p><br/></p><p><span style="font-family:Verd